/** Journeys (tours). Drives /tours and /tours/[slug].
 *  The journeys are bespoke designs rendered verbatim from
 *  content/tours/<slug>.json. This file is a thin index for the cards,
 *  homepage and plan dropdown — generated by scripts/build-journeys.mjs. */

export type GradientVariant =
  | "nile" | "desert" | "ancient" | "oasis" | "sunset" | "night";

export interface ItineraryDay { day: number; title: string; description: string; }

export interface Tour {
  slug: string;
  type: string;
  title: string;
  tagline: string;
  description: string;
  intro: string;
  durationDays: number;
  duration: string;
  groupType: string;
  gradient: GradientVariant;
  heroLabel: string;
  featured: boolean;
  regions: string[];
  highlights: string[];
  itinerary: ItineraryDay[];
  included: string[];
  guideSlug: string;
  galleryLabels: string[];
  seo: { title: string; description: string };
  route?: string;
  pace?: string;
  journeyHeadline?: string;
  differentiators?: { title: string; description: string }[];
  caveat?: { title: string; body: string[] };
  notIncluded?: string[];
  /** Bespoke journeys render verbatim from content/tours/<slug>.json. */
  bespoke?: boolean;
  /** "From" price per person in EUR, shown on the journey cards. */
  fromPrice?: number;
}

